```js
async function draftEmail(topic, client) {
  const res = await client.messages.create({
    model: 'claude-3-haiku-20240307', max_tokens: 200,
    messages: [{ role: 'user', content: `Draft a short email about: ${topic}` }]
  });
  return res.content[0].text;
}

// test
it('returns mocked text', async () => {
  const mock = { messages: { create: async () => ({ content: [{ text: 'Hi there,' }] }) } };
  expect(await draftEmail('a meeting', mock)).toBe('Hi there,');
});

it('propagates API errors', async () => {
  const mock = { messages: { create: async () => { throw new Error('Rate limited'); } } };
  await expect(draftEmail('x', mock)).rejects.toThrow('Rate limited');
});
```

