explanation:
```js
async function summarize(text, client, { verbose = false } = {}) {
  const system = 'Summarize this in 2 sentences.';
  if (verbose) {
    console.error('--- PROMPT ---');
    console.error('System:', system);
    console.error('Input:', text.slice(0, 200));
  }
  const res = await client.messages.create({ model: 'claude-3-haiku-20240307', max_tokens: 200, system, messages: [{ role: 'user', content: text }] });
  if (verbose) {
    console.error('--- RAW RESPONSE ---');
    console.error(JSON.stringify(res, null, 2));
  }
  return res.content[0].text;
}
```

