function validateInput(text) {
  const trimmed = text.trim();
  if (trimmed.length === 0) throw new Error('No input provided. Paste some text and try again.');
  const words = trimmed.split(/\s+/);
  if (words.length > 5000) throw new Error(`Input is ${words.length} words — this tool handles up to 5,000. Try a shorter excerpt.`);
  if (words.length < 5) throw new Error('Input is too short to summarize meaningfully.');
  return trimmed;
}
```
